import { EChartsType } from '@/src/echarts';
import { createChart, getECModel, getGraphicElements, removeChart } from '../../../core/utHelper';

type LineViewLike = {
    _points: ArrayLike<number>
    _stackedOnPoints: ArrayLike<number>
};

function getSeriesView(chart: EChartsType, seriesIndex?: number): LineViewLike {
    const seriesModel = getECModel(chart).getComponent('series', seriesIndex || 0);
    return (chart as any)._chartsMap[(seriesModel as any).__viewId];
}

function getPolyPoints(chart: EChartsType, type: 'ec-polyline' | 'ec-polygon'): ArrayLike<number> {
    const els = getGraphicElements(chart, 'series', 0);
    for (let i = 0; i < els.length; i++) {
        if (els[i].type === type) {
            return (els[i] as any).shape.points;
        }
    }
    return null;
}

function makeOption(animation: boolean, data: (number | null)[], step?: 'start' | 'middle' | 'end') {
    return {
        animation,
        xAxis: {
            type: 'category' as const,
            data: ['a', 'b', 'c', 'd']
        },
        yAxis: {},
        series: [{
            type: 'line' as const,
            step,
            areaStyle: {},
            data
        }]
    };
}

describe('chart/line/memory', function () {

    let chart: EChartsType;
    beforeEach(function () {
        chart = createChart();
    });
    afterEach(function () {
        removeChart(chart);
    });

    it('should not retain the transition buffers when there is no animation', function () {
        chart.setOption(makeOption(false, [10, 20, 30, 40]));

        const view = getSeriesView(chart);
        // They are only used by the transition animation of the next render.
        expect(view._points).toBeNull();
        expect(view._stackedOnPoints).toBeNull();
    });

    it('should still retain the transition buffers when animation is enabled', function () {
        chart.setOption(makeOption(true, [10, 20, 30, 40]));

        const view = getSeriesView(chart);
        expect(view._points).not.toBeNull();
        expect(view._stackedOnPoints).not.toBeNull();
        // `_points` is the layout array itself, not a copy of it.
        expect(view._points).toBe(getECModel(chart).getSeriesByIndex(0).getData().getLayout('points'));
    });

    it('should keep updating the shape after the transition buffers were released', function () {
        chart.setOption(makeOption(false, [10, 20, 30, 40]));
        const before = Array.prototype.slice.call(getPolyPoints(chart, 'ec-polyline'));

        chart.setOption(makeOption(false, [40, 30, 20, 10]));
        const after = Array.prototype.slice.call(getPolyPoints(chart, 'ec-polyline'));

        expect(after.length).toEqual(before.length);
        expect(after).not.toEqual(before);
    });

    it('should not break when animation is switched on after being off', function () {
        chart.setOption(makeOption(false, [10, 20, 30, 40]));
        expect(function () {
            chart.setOption(makeOption(true, [40, 30, 20, 10]));
        }).not.toThrow();
        expect(getSeriesView(chart)._points).not.toBeNull();
    });

    it('should store step points in a compact typed array', function () {
        chart.setOption(makeOption(false, [10, 20, 30, 40], 'middle'));

        const points = getPolyPoints(chart, 'ec-polyline');
        // A plain array of doubles costs about twice the memory of a Float32Array,
        // and the raw layout points are float32 anyway.
        expect(points instanceof Float32Array).toBe(true);
        // 4 data points turn into 4 * 3 - 2 = 10 step points.
        expect(points.length).toEqual(20);

        const stackedOnPoints = (function () {
            const els = getGraphicElements(chart, 'series', 0);
            for (let i = 0; i < els.length; i++) {
                if (els[i].type === 'ec-polygon') {
                    return (els[i] as any).shape.stackedOnPoints;
                }
            }
            return null;
        })();
        expect(stackedOnPoints instanceof Float32Array).toBe(true);
        expect(stackedOnPoints.length).toEqual(20);
    });
});

