/*
 * TEMP verification test - compares the new turnPointsIntoStep output against a
 * literal re-implementation of the pre-change (HEAD) algorithm.
 */
import { EChartsType } from '@/src/echarts';
import { createChart, getECModel, getGraphicElements, removeChart } from '../../../core/utHelper';

function refTurnPointsIntoStep(
    points: ArrayLike<number>,
    coordSys: {baseIndex: number},
    stepTurnAt: 'start' | 'end' | 'middle',
    connectNulls: boolean
): number[] {
    const baseIndex = coordSys.baseIndex;
    const stepPoints: number[] = [];
    let i = 0;
    const stepPt: number[] = [];
    const pt: number[] = [];
    const nextPt: number[] = [];
    const filteredPoints: number[] = [];
    if (connectNulls) {
        for (i = 0; i < points.length; i += 2) {
            if (!isNaN(points[i]) && !isNaN(points[i + 1])) {
                filteredPoints.push(points[i], points[i + 1]);
            }
        }
        points = filteredPoints;
    }
    for (i = 0; i < points.length - 2; i += 2) {
        nextPt[0] = points[i + 2];
        nextPt[1] = points[i + 3];
        pt[0] = points[i];
        pt[1] = points[i + 1];
        stepPoints.push(pt[0], pt[1]);

        switch (stepTurnAt) {
            case 'end':
                stepPt[baseIndex] = nextPt[baseIndex];
                stepPt[1 - baseIndex] = pt[1 - baseIndex];
                stepPoints.push(stepPt[0], stepPt[1]);
                break;
            case 'middle':
                const middle = (pt[baseIndex] + nextPt[baseIndex]) / 2;
                const stepPt2: number[] = [];
                stepPt[baseIndex] = stepPt2[baseIndex] = middle;
                stepPt[1 - baseIndex] = pt[1 - baseIndex];
                stepPt2[1 - baseIndex] = nextPt[1 - baseIndex];
                stepPoints.push(stepPt[0], stepPt[1]);
                stepPoints.push(stepPt2[0], stepPt2[1]);
                break;
            default:
                stepPt[baseIndex] = pt[baseIndex];
                stepPt[1 - baseIndex] = nextPt[1 - baseIndex];
                stepPoints.push(stepPt[0], stepPt[1]);
        }
    }
    if (points.length >= 2) {
        stepPoints.push(points[i], points[i + 1]);
    }
    return stepPoints;
}

function getShape(chart: EChartsType, type: 'ec-polyline' | 'ec-polygon'): any {
    const els = getGraphicElements(chart, 'series', 0);
    for (let i = 0; i < els.length; i++) {
        if (els[i].type === type) {
            return (els[i] as any).shape;
        }
    }
    return null;
}

function layoutPoints(chart: EChartsType): ArrayLike<number> {
    return getECModel(chart).getSeriesByIndex(0).getData().getLayout('points') as ArrayLike<number>;
}

function toArr(a: ArrayLike<number>): number[] {
    return Array.prototype.slice.call(a);
}

// float32 rounding for the reference values
function f32(a: number[]): number[] {
    const t = new Float32Array(a);
    return Array.prototype.slice.call(t);
}

describe('turnPointsIntoStep parity', function () {
    let chart: EChartsType;
    beforeEach(function () {
        chart = createChart();
    });
    afterEach(function () {
        removeChart(chart);
    });

    const dataSets: {name: string, data: any[]}[] = [
        {name: 'plain', data: [10, 20, 30, 40, 50]},
        {name: 'leading null', data: [null, 20, 30, 40, 50]},
        {name: 'middle null', data: [10, 20, null, 40, 50]},
        {name: 'trailing null', data: [10, 20, 30, 40, null]},
        {name: 'multi null', data: [10, null, null, 40, null]},
        {name: 'all null', data: [null, null, null, null, null]},
        {name: 'single', data: [10]},
        {name: 'single null', data: [null]},
        {name: 'empty', data: []}
    ];
    const steps: ('start' | 'middle' | 'end')[] = ['start', 'middle', 'end'];

    steps.forEach(step => {
        [false, true].forEach(connectNulls => {
            [false, true].forEach(vertical => {
                dataSets.forEach(ds => {
                    const title = `step=${step} connectNulls=${connectNulls} vertical=${vertical} data=${ds.name}`;
                    it(title, function () {
                        const cat = {
                            type: 'category' as const,
                            data: ['a', 'b', 'c', 'd', 'e']
                        };
                        const val = {type: 'value' as const};
                        const seriesData = vertical
                            ? ds.data.map((v, i) => [v, i])
                            : ds.data;
                        chart.setOption({
                            animation: false,
                            xAxis: vertical ? val : cat,
                            yAxis: vertical ? cat : val,
                            series: [{
                                type: 'line' as const,
                                step,
                                connectNulls,
                                areaStyle: {},
                                data: seriesData
                            }]
                        }, true);

                        const baseIndex = vertical ? 1 : 0;
                        const src = layoutPoints(chart);
                        const expected = f32(refTurnPointsIntoStep(src, {baseIndex}, step, connectNulls));

                        const lineShape = getShape(chart, 'ec-polyline');
                        expect(lineShape).not.toBeNull();
                        expect(toArr(lineShape.points)).toEqual(expected);

                        // now the stacked-on / area base line
                        const polyShape = getShape(chart, 'ec-polygon');
                        expect(polyShape).not.toBeNull();
                        expect(polyShape.points).toBe(lineShape.points);

                        // Get the raw (non-step) stackedOnPoints for the same data
                        chart.setOption({
                            animation: false,
                            xAxis: vertical ? val : cat,
                            yAxis: vertical ? cat : val,
                            series: [{
                                type: 'line' as const,
                                connectNulls,
                                areaStyle: {},
                                data: seriesData
                            }]
                        }, true);
                        const rawStackedOn = getShape(chart, 'ec-polygon').stackedOnPoints;
                        const expectedStackedOn = f32(
                            refTurnPointsIntoStep(rawStackedOn, {baseIndex}, step, connectNulls)
                        );
                        // NOTE: the reference filtered rawStackedOn by ITS OWN NaN-ness in the
                        // connectNulls case (that was the #20092 bug). Only compare when there
                        // are no nulls, or when connectNulls is off.
                        if (!connectNulls) {
                            expect(toArr(polyShape.stackedOnPoints)).toEqual(expectedStackedOn);
                        }
                        // Index alignment invariant: same length as points.
                        expect(polyShape.stackedOnPoints.length).toEqual(lineShape.points.length);
                    });
                });
            });
        });
    });
});

