/*
 * TEMP verification test: animated update paths with step + connectNulls, and
 * animation toggling / dataZoom.
 */
import { EChartsType } from '@/src/echarts';
import { createChart, getECModel, getGraphicElements, removeChart } from '../../../core/utHelper';

function getShape(chart: EChartsType, type: 'ec-polyline' | 'ec-polygon'): any {
    const els = getGraphicElements(chart, 'series', 0);
    for (let i = 0; i < els.length; i++) {
        if (els[i].type === type) {
            return (els[i] as any).shape;
        }
    }
    return null;
}

function getView(chart: EChartsType): any {
    const seriesModel = getECModel(chart).getComponent('series', 0);
    return (chart as any)._chartsMap[(seriesModel as any).__viewId];
}

describe('line memory reduction - animated paths', function () {
    let chart: EChartsType;
    beforeEach(function () {
        chart = createChart();
    });
    afterEach(function () {
        removeChart(chart);
    });

    const steps: (undefined | 'start' | 'middle' | 'end')[] = [undefined, 'start', 'middle', 'end'];

    steps.forEach(step => {
        [false, true].forEach(connectNulls => {
            it(`animated update step=${step} connectNulls=${connectNulls}: value -> null`, function () {
                const opt = (data: any[]) => ({
                    animation: true,
                    xAxis: {type: 'category' as const, data: ['a', 'b', 'c', 'd', 'e']},
                    yAxis: {},
                    series: [{type: 'line' as const, step, connectNulls, areaStyle: {}, data}]
                });
                chart.setOption(opt([10, 20, 30, 40, 50]));
                expect(function () {
                    chart.setOption(opt([10, 20, null, 40, 50]));
                }).not.toThrow();
                const s = getShape(chart, 'ec-polyline');
                expect(s.points.length % 2).toBe(0);
                expect(getShape(chart, 'ec-polygon').stackedOnPoints.length).toBe(s.points.length);
            });

            it(`animated update step=${step} connectNulls=${connectNulls}: null -> value`, function () {
                const opt = (data: any[]) => ({
                    animation: true,
                    xAxis: {type: 'category' as const, data: ['a', 'b', 'c', 'd', 'e']},
                    yAxis: {},
                    series: [{type: 'line' as const, step, connectNulls, areaStyle: {}, data}]
                });
                chart.setOption(opt([10, 20, null, 40, 50]));
                expect(function () {
                    chart.setOption(opt([10, 20, 30, 40, 50]));
                }).not.toThrow();
                const s = getShape(chart, 'ec-polyline');
                expect(getShape(chart, 'ec-polygon').stackedOnPoints.length).toBe(s.points.length);
            });

            it(`animated update step=${step} connectNulls=${connectNulls}: data appended`, function () {
                const opt = (cats: string[], data: any[]) => ({
                    animation: true,
                    xAxis: {type: 'category' as const, data: cats},
                    yAxis: {},
                    series: [{type: 'line' as const, step, connectNulls, areaStyle: {}, data}]
                });
                chart.setOption(opt(['a', 'b', 'c'], [10, 20, 30]));
                expect(function () {
                    chart.setOption(opt(['a', 'b', 'c', 'd', 'e'], [10, 20, 30, 40, 50]));
                }).not.toThrow();
                const s = getShape(chart, 'ec-polyline');
                const expectedPts = step === 'middle' ? 5 * 3 - 2 : (step ? 5 * 2 - 1 : 5);
                // After the animation target is applied, the shape must be able to
                // hold all of the new points.
                expect(s.points.length).toBe(expectedPts * 2);
            });
        });
    });

    it('animation off -> on -> off across setOption', function () {
        const opt = (animation: boolean, data: any[]) => ({
            animation,
            xAxis: {type: 'category' as const, data: ['a', 'b', 'c', 'd']},
            yAxis: {},
            series: [{type: 'line' as const, step: 'middle' as const, areaStyle: {}, data}]
        });
        chart.setOption(opt(false, [1, 2, 3, 4]));
        expect(getView(chart)._points).toBeNull();
        chart.setOption(opt(true, [4, 3, 2, 1]));
        expect(getView(chart)._points).not.toBeNull();
        chart.setOption(opt(false, [1, 4, 2, 3]));
        expect(getView(chart)._points).toBeNull();
        chart.setOption(opt(true, [2, 2, 2, 2]));
        expect(getView(chart)._points).not.toBeNull();
        // shape stays in sync
        const s = getShape(chart, 'ec-polyline');
        expect(s.points.length).toBe((4 * 3 - 2) * 2);
    });

    it('dataZoom updates with animation off', function () {
        const data: number[] = [];
        const cats: string[] = [];
        for (let i = 0; i < 50; i++) {
            data.push(i % 7);
            cats.push('c' + i);
        }
        chart.setOption({
            animation: false,
            xAxis: {type: 'category', data: cats},
            yAxis: {},
            dataZoom: [{type: 'inside', start: 0, end: 100}],
            series: [{type: 'line', step: 'start', areaStyle: {}, data}]
        });
        const before = getShape(chart, 'ec-polyline').points.length;
        expect(function () {
            chart.dispatchAction({type: 'dataZoom', start: 20, end: 60});
        }).not.toThrow();
        const after = getShape(chart, 'ec-polyline').points.length;
        expect(after).toBeLessThan(before);
        expect(getView(chart)._points).toBeNull();
        // zoom back
        chart.dispatchAction({type: 'dataZoom', start: 0, end: 100});
        expect(getShape(chart, 'ec-polyline').points.length).toBe(before);
    });

    it('dataZoom updates with animation on', function () {
        const data: number[] = [];
        const cats: string[] = [];
        for (let i = 0; i < 50; i++) {
            data.push(i % 7);
            cats.push('c' + i);
        }
        chart.setOption({
            animation: true,
            xAxis: {type: 'category', data: cats},
            yAxis: {},
            dataZoom: [{type: 'inside', start: 0, end: 100}],
            series: [{type: 'line', step: 'start', areaStyle: {}, data}]
        });
        expect(function () {
            chart.dispatchAction({type: 'dataZoom', start: 20, end: 60});
            chart.dispatchAction({type: 'dataZoom', start: 0, end: 100});
        }).not.toThrow();
    });

    it('areaStyle added / removed while animation is off', function () {
        const opt = (area: boolean) => ({
            animation: false,
            xAxis: {type: 'category' as const, data: ['a', 'b', 'c', 'd']},
            yAxis: {},
            series: [{
                type: 'line' as const,
                step: 'end' as const,
                areaStyle: area ? {} : undefined,
                data: [1, 2, 3, 4]
            }]
        });
        chart.setOption(opt(false));
        expect(getShape(chart, 'ec-polygon')).toBeNull();
        expect(function () {
            chart.setOption(opt(true), true);
        }).not.toThrow();
        const p = getShape(chart, 'ec-polygon');
        expect(p).not.toBeNull();
        expect(p.stackedOnPoints.length).toBe(p.points.length);
    });
});

import { ECPolyline } from '@/src/chart/line/poly';
import * as graphic from '@/src/util/graphic';
import Model from '@/src/model/Model';

describe('zrender typed-array shape.points animation', function () {
    it('cannot grow a Float32Array shape.points when the target is longer', function () {
        const current = new Float32Array([0, 0, 10, 10]);
        const next = new Float32Array([0, 0, 10, 10, 20, 20]);
        const el = new ECPolyline({shape: {points: current}});
        const seriesModel = new Model({animation: true, animationDurationUpdate: 100}) as any;
        seriesModel.getShallow = function (k: string) {
            return (this.option as any)[k];
        };
        graphic.updateProps(el as any, {shape: {points: next}} as any, seriesModel);
        // force the animation to its end
        (el.animators || []).forEach(a => {
            (a as any).setTime(1000);
            (a as any).step(1000, 1000);
        });
        // eslint-disable-next-line no-console
        console.log('typed array result length', el.shape.points.length,
            Array.prototype.slice.call(el.shape.points));

        const currentPlain = [0, 0, 10, 10];
        const el2 = new ECPolyline({shape: {points: currentPlain}});
        graphic.updateProps(el2 as any, {shape: {points: [0, 0, 10, 10, 20, 20]}} as any, seriesModel);
        (el2.animators || []).forEach(a => {
            (a as any).setTime(1000);
            (a as any).step(1000, 1000);
        });
        // eslint-disable-next-line no-console
        console.log('plain array result length', el2.shape.points.length,
            Array.prototype.slice.call(el2.shape.points));
    });
});

