import { EChartsType } from '@/src/echarts';
import { createChart, getGraphicElements, removeChart } from '../../../core/utHelper';

function getEl(chart: EChartsType, type: string): any {
    const els = getGraphicElements(chart, 'series', 0);
    for (let i = 0; i < els.length; i++) {
        if (els[i].type === type) {
            return els[i];
        }
    }
    return null;
}

describe('probe: in-place mutation of Float32Array shape.points during animation', function () {
    let chart: EChartsType;
    beforeEach(function () {
        chart = createChart();
    });
    afterEach(function () {
        removeChart(chart);
    });

    it('step line: shape.points identity/length during and after animation', function () {
        const opt = (data: any[]) => ({
            animation: true,
            animationDurationUpdate: 100,
            xAxis: {type: 'category' as const, data: ['a', 'b', 'c', 'd', 'e']},
            yAxis: {},
            series: [{
                type: 'line' as const, step: 'start' as const, connectNulls: true,
                areaStyle: {}, data
            }]
        });
        chart.setOption(opt([10, 20, 30, 40, 50]));
        const el0 = getEl(chart, 'ec-polyline');
        chart.setOption(opt([10, 20, null, 40, 50]));
        const el = getEl(chart, 'ec-polyline');
        // eslint-disable-next-line no-console
        console.log('same el?', el === el0);
        const ptsBefore = el.shape.points;
        // eslint-disable-next-line no-console
        console.log('before frame: isF32', ptsBefore instanceof Float32Array,
            'len', ptsBefore.length, Array.prototype.slice.call(ptsBefore));
        const zr = (chart as any).getZr();
        // advance animation to the end
        zr.animation.update(true);
        for (let i = 0; i < 30; i++) {
            (el.animators || []).forEach((a: any) => a.__setTime && a.__setTime());
            zr.animation.update(true);
        }
        const ptsAfter = el.shape.points;
        // eslint-disable-next-line no-console
        console.log('after frames: sameRef', ptsAfter === ptsBefore,
            'isF32', ptsAfter instanceof Float32Array,
            'len', ptsAfter.length, Array.prototype.slice.call(ptsAfter));
        // eslint-disable-next-line no-console
        console.log('animators', (el.animators || []).length);
    });
});

