/*
 * TEMP verification: parity of the revised turnPointsIntoStep + getStackedOnPoints
 * buffer reuse against the pre-change (HEAD~) algorithm.
 */
import { EChartsType } from '@/src/echarts';
import { createChart, getECModel, getGraphicElements, removeChart } from '../../../core/utHelper';

function refTurnPointsIntoStep(
    points: ArrayLike<number>,
    baseIndex: number,
    stepTurnAt: 'start' | 'end' | 'middle',
    connectNulls: boolean
): number[] {
    const stepPoints: number[] = [];
    let i = 0;
    const stepPt: number[] = [];
    const pt: number[] = [];
    const nextPt: number[] = [];
    const filteredPoints: number[] = [];
    if (connectNulls) {
        for (i = 0; i < points.length; i += 2) {
            if (!isNaN(points[i]) && !isNaN(points[i + 1])) {
                filteredPoints.push(points[i], points[i + 1]);
            }
        }
        points = filteredPoints;
    }
    for (i = 0; i < points.length - 2; i += 2) {
        nextPt[0] = points[i + 2];
        nextPt[1] = points[i + 3];
        pt[0] = points[i];
        pt[1] = points[i + 1];
        stepPoints.push(pt[0], pt[1]);
        switch (stepTurnAt) {
            case 'end':
                stepPt[baseIndex] = nextPt[baseIndex];
                stepPt[1 - baseIndex] = pt[1 - baseIndex];
                stepPoints.push(stepPt[0], stepPt[1]);
                break;
            case 'middle':
                const middle = (pt[baseIndex] + nextPt[baseIndex]) / 2;
                const stepPt2: number[] = [];
                stepPt[baseIndex] = stepPt2[baseIndex] = middle;
                stepPt[1 - baseIndex] = pt[1 - baseIndex];
                stepPt2[1 - baseIndex] = nextPt[1 - baseIndex];
                stepPoints.push(stepPt[0], stepPt[1]);
                stepPoints.push(stepPt2[0], stepPt2[1]);
                break;
            default:
                stepPt[baseIndex] = pt[baseIndex];
                stepPt[1 - baseIndex] = nextPt[1 - baseIndex];
                stepPoints.push(stepPt[0], stepPt[1]);
        }
    }
    if (points.length >= 2) {
        stepPoints.push(points[i], points[i + 1]);
    }
    return stepPoints;
}

function getShape(chart: EChartsType, type: string, seriesIndex?: number): any {
    const els = getGraphicElements(chart, 'series', seriesIndex || 0);
    for (let i = 0; i < els.length; i++) {
        if (els[i].type === type) {
            return (els[i] as any).shape;
        }
    }
    return null;
}

function layoutPoints(chart: EChartsType, seriesIndex?: number): ArrayLike<number> {
    return (getECModel(chart).getSeriesByIndex(seriesIndex || 0)
        .getData().getLayout('points') as ArrayLike<number>) || [];
}

function toArr(a: ArrayLike<number>): number[] {
    return Array.prototype.slice.call(a);
}
function f32(a: number[]): number[] {
    return Array.prototype.slice.call(new Float32Array(a));
}

describe('revised turnPointsIntoStep parity', function () {
    let chart: EChartsType;
    beforeEach(function () {
        chart = createChart();
    });
    afterEach(function () {
        removeChart(chart);
    });

    const dataSets = [
        {name: 'plain', data: [10, 20, 30, 40, 50]},
        {name: 'leading null', data: [null, 20, 30, 40, 50]},
        {name: 'middle null', data: [10, 20, null, 40, 50]},
        {name: 'trailing null', data: [10, 20, 30, 40, null]},
        {name: 'multi null', data: [10, null, null, 40, null]},
        {name: 'all null', data: [null, null, null, null, null]},
        {name: 'single', data: [10]},
        {name: 'single null', data: [null]},
        {name: 'empty', data: [] as any[]}
    ];
    const steps: ('start' | 'middle' | 'end')[] = ['start', 'middle', 'end'];

    steps.forEach(step => {
        [false, true].forEach(connectNulls => {
            [false, true].forEach(vertical => {
                dataSets.forEach(ds => {
                    it(`step=${step} cn=${connectNulls} vert=${vertical} ${ds.name}`, function () {
                        const cat = {type: 'category' as const, data: ['a', 'b', 'c', 'd', 'e']};
                        const val = {type: 'value' as const};
                        const seriesData = vertical ? ds.data.map((v, i) => [v, i]) : ds.data;
                        const mkOpt = (withStep: boolean) => ({
                            animation: false,
                            xAxis: vertical ? val : cat,
                            yAxis: vertical ? cat : val,
                            series: [{
                                type: 'line' as const,
                                step: withStep ? step : undefined,
                                connectNulls,
                                areaStyle: {},
                                data: seriesData
                            }]
                        });
                        chart.setOption(mkOpt(true), true);
                        const baseIndex = vertical ? 1 : 0;
                        const src = layoutPoints(chart);
                        const expected = f32(refTurnPointsIntoStep(src, baseIndex, step, connectNulls));
                        const lineShape = getShape(chart, 'ec-polyline');
                        const polyShape = getShape(chart, 'ec-polygon');
                        const actualPoints = toArr(lineShape.points);
                        const actualStackedOn = toArr(polyShape.stackedOnPoints);
                        expect(actualPoints).toEqual(expected);
                        expect(polyShape.points).toBe(lineShape.points);
                        expect(actualStackedOn.length).toEqual(actualPoints.length);
                        expect(actualPoints.length === 0
                            || lineShape.points instanceof Float32Array).toBe(true);

                        // Raw (non-step) stackedOnPoints for the same data, then
                        // step it with the reference algorithm.
                        chart.setOption(mkOpt(false), true);
                        const rawStackedOn = getShape(chart, 'ec-polygon').stackedOnPoints;
                        if (!connectNulls) {
                            expect(actualStackedOn).toEqual(
                                f32(refTurnPointsIntoStep(rawStackedOn, baseIndex, step, connectNulls))
                            );
                        }
                    });
                });
            });
        });
    });

    it('stacked cartesian area: stackedOnPoints match the series below (buffer reuse)', function () {
        chart.setOption({
            animation: false,
            xAxis: {type: 'category', data: ['a', 'b', 'c', 'd', 'e']},
            yAxis: {},
            series: [
                {type: 'line', stack: 's', areaStyle: {}, data: [10, 20, 30, 40, 50]},
                {type: 'line', stack: 's', areaStyle: {}, data: [5, 15, 25, 35, 45]}
            ]
        });
        const below = layoutPoints(chart, 0);
        const above = getShape(chart, 'ec-polygon', 1);
        expect(toArr(above.stackedOnPoints)).toEqual(toArr(below));
        // sanity: the values must not all be the same (buffer aliasing symptom)
        const ys = toArr(above.stackedOnPoints).filter((v, i) => i % 2 === 1);
        expect(new Set(ys).size).toBeGreaterThan(1);
    });

    it('polar area chart: stackedOnPoints are per-item (out buffer reuse)', function () {
        chart.setOption({
            animation: false,
            polar: {},
            angleAxis: {type: 'category', data: ['a', 'b', 'c', 'd', 'e']},
            radiusAxis: {},
            series: [{type: 'line', coordinateSystem: 'polar', areaStyle: {}, data: [10, 20, 30, 40, 50]}]
        });
        const p = getShape(chart, 'ec-polygon');
        expect(p).not.toBeNull();
        const so = toArr(p.stackedOnPoints);
        expect(so.length).toEqual(10);
        so.forEach(v => expect(isFinite(v)).toBe(true));
        // The origin of every ray is the polar center -> all equal is CORRECT here,
        // so instead check against an independent computation.
        const polar = (getECModel(chart).getSeriesByIndex(0) as any).coordinateSystem;
        for (let i = 0; i < 5; i++) {
            const ref = polar.dataToPoint([0, i]);
            expect(so[i * 2]).toBeCloseTo(ref[0], 3);
            expect(so[i * 2 + 1]).toBeCloseTo(ref[1], 3);
        }
    });

    it('stacked polar area chart: stackedOnPoints follow the series below', function () {
        chart.setOption({
            animation: false,
            polar: {},
            angleAxis: {type: 'category', data: ['a', 'b', 'c', 'd', 'e']},
            radiusAxis: {},
            series: [
                {type: 'line', coordinateSystem: 'polar', stack: 's', areaStyle: {},
                    data: [10, 20, 30, 40, 50]},
                {type: 'line', coordinateSystem: 'polar', stack: 's', areaStyle: {},
                    data: [5, 15, 25, 35, 45]}
            ]
        });
        const below = layoutPoints(chart, 0);
        const above = getShape(chart, 'ec-polygon', 1);
        const so = toArr(above.stackedOnPoints);
        expect(so.length).toEqual(toArr(below).length);
        for (let i = 0; i < so.length; i++) {
            expect(so[i]).toBeCloseTo(below[i], 3);
        }
    });

    it('polar dataToPoint/coordToPoint out param does not leak', function () {
        chart.setOption({
            animation: false,
            polar: {},
            angleAxis: {type: 'category', data: ['a', 'b', 'c']},
            radiusAxis: {},
            series: [{type: 'line', coordinateSystem: 'polar', data: [1, 2, 3]}]
        });
        const polar = (getECModel(chart).getSeriesByIndex(0) as any).coordinateSystem;
        const a = polar.dataToPoint([1, 0]);
        const b = polar.dataToPoint([2, 1]);
        expect(a).not.toBe(b);
        const out: number[] = [];
        const c = polar.dataToPoint([3, 2], false, out);
        expect(c).toBe(out);
        expect(out.length).toBe(2);
        const d = polar.coordToPoint([10, 45]);
        const e = polar.coordToPoint([10, 45], out);
        expect(e).toBe(out);
        expect(toArr(d)).toEqual(toArr(e));
    });

    it('clamp default (undefined) vs false is equivalent for stacked-on points', function () {
        // A value axis with min/max narrower than the data exercises clamping.
        chart.setOption({
            animation: false,
            xAxis: {type: 'category', data: ['a', 'b', 'c', 'd', 'e']},
            yAxis: {min: 15, max: 35},
            series: [{type: 'line', areaStyle: {origin: 'start'}, data: [10, 20, 30, 40, 50]}]
        });
        const p = getShape(chart, 'ec-polygon');
        const so = toArr(p.stackedOnPoints);
        const polar = (getECModel(chart).getSeriesByIndex(0) as any).coordinateSystem;
        // origin 'start' -> yAxis extent start; the point must be unclamped, i.e.
        // identical to dataToPoint without a clamp argument.
        for (let i = 0; i < 5; i++) {
            const ref = polar.dataToPoint([i, 15]);
            expect(so[i * 2]).toBeCloseTo(ref[0], 3);
        }
        so.forEach(v => expect(isNaN(v)).toBe(false));
    });
});

