import { EChartsType } from '@/src/echarts';
import { createChart, getGraphicElements, removeChart } from '../../../core/utHelper';

function getShape(chart: EChartsType, type: string): any {
    const els = getGraphicElements(chart, 'series', 0);
    for (let i = 0; i < els.length; i++) {
        if (els[i].type === type) {
            return (els[i] as any).shape;
        }
    }
    return null;
}

describe('animated step update paths', function () {
    let chart: EChartsType;
    beforeEach(function () {
        chart = createChart();
    });
    afterEach(function () {
        removeChart(chart);
    });

    const steps: (undefined | 'start' | 'middle' | 'end')[] = [undefined, 'start', 'middle', 'end'];
    steps.forEach(step => {
        [false, true].forEach(connectNulls => {
            const opt = (cats: string[], data: any[]) => ({
                animation: true,
                animationDurationUpdate: 50,
                xAxis: {type: 'category' as const, data: cats},
                yAxis: {},
                series: [{type: 'line' as const, step, connectNulls, areaStyle: {}, data}]
            });
            const cats = ['a', 'b', 'c', 'd', 'e'];
            it(`step=${step} cn=${connectNulls}: value->null, null->value, append, shrink`, function () {
                chart.setOption(opt(cats, [10, 20, 30, 40, 50]));
                const zr = (chart as any).getZr();
                const seqs: any[][] = [
                    [10, 20, null, 40, 50],
                    [10, 20, 30, 40, 50],
                    [null, null, 30, 40, null],
                    [1, 2, 3, 4, 5]
                ];
                seqs.forEach(d => {
                    expect(function () {
                        chart.setOption(opt(cats, d));
                        zr.animation.update(true);
                    }).not.toThrow();
                    const s = getShape(chart, 'ec-polyline');
                    const p = getShape(chart, 'ec-polygon');
                    expect(s.points.length % 2).toBe(0);
                    expect(p.stackedOnPoints.length).toBe(s.points.length);
                });
                // grow / shrink the category count
                expect(function () {
                    chart.setOption(opt(['a', 'b', 'c'], [1, 2, 3]), true);
